#!/usr/bin/env node
/**
 * Launcher for the Claude Code plugin and for anyone running from a checkout.
 *
 * This is Node rather than a shell script on purpose: the plugin manifest names
 * it as the MCP `command`, and Windows does not interpret a `#!` line — a bash
 * shim there simply fails to start, silently, on the one client this project
 * treats as first-class. Node is guaranteed present, because the thing being
 * launched is a Node package.
 *
 * A plugin installed from git arrives as source with no build step, so this
 * builds once on first use and then runs the compiled CLI. Published npm users
 * never touch this file — they run `npx @pebbly/aseprite-ai-artist`.
 */

import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { buildSteps } from "./launcher.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const cli = path.join(root, "dist", "cli.js");

// stderr only: stdout is the MCP stdio channel and any stray byte corrupts it.
const log = (msg) => process.stderr.write(`[aseprite-ai-artist] ${msg}\n`);

if (!existsSync(cli)) {
  log("first run — building…");
  // `shell: true` so npm resolves as npm.cmd on Windows.
  const steps = buildSteps();
  for (const args of steps) {
    const result = spawnSync("npm", args, { cwd: root, stdio: ["ignore", 2, 2], shell: true });
    if (result.status !== 0) {
      log(`build step \`npm ${args.join(" ")}\` failed with status ${result.status}.`);
      process.exit(result.status ?? 1);
    }
  }
}

const child = spawnSync(process.execPath, [cli, ...process.argv.slice(2)], { stdio: "inherit" });
process.exit(child.status ?? 1);

/**
 * The bootstrap a git-installed plugin runs once, kept out of the entry point
 * so a test can read it without executing npm.
 *
 * `npm ci`, not `npm install`: a git install carries package-lock.json, and
 * `ci` refuses to resolve anything the lockfile did not pin. `--ignore-scripts`
 * because dependency lifecycle scripts are the remote-code half of a
 * supply-chain compromise and nothing here needs them: CI's `launcher` job
 * builds this same tree under exactly these flags.
 */
export function buildSteps() {
  return [
    ["ci", "--silent", "--no-audit", "--no-fund", "--ignore-scripts"],
    ["run", "--silent", "build"],
  ];
}

#!/usr/bin/env node
/**
 * One binary, several jobs:
 *   serve              (default) speak MCP over stdio
 *   bridge             run the singleton WebSocket relay
 *   install <client…>  wire this server into an agent's config
 *   install-extension  copy the Lua extension into Aseprite
 *   doctor             tell the user exactly what is broken
 */
import path from "node:path";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { Bridge } from "./bridge/bridge.js";
import { LiveClient } from "./bridge/client.js";
import { createServer } from "./server.js";
import { CLIENTS, configPath, install, mergeAgentsFile, } from "./install.js";
import { installExtension, findAsepriteBinary, findAsepriteConfigDir } from "./extension.js";
import { DEFAULT_CONTROL_PORT, DEFAULT_PLUGIN_PORT } from "./lib/protocol.js";
import { packageVersion } from "./lib/version.js";
import { linkLines } from "./lib/report.js";
function parseArgs(argv) {
    const flags = {};
    const positional = [];
    for (let i = 0; i < argv.length; i++) {
        const arg = argv[i];
        if (!arg.startsWith("--")) {
            positional.push(arg);
            continue;
        }
        const key = arg.slice(2);
        const next = argv[i + 1];
        if (next !== undefined && !next.startsWith("--")) {
            flags[key] = next;
            i++;
        }
        else {
            flags[key] = true;
        }
    }
    const command = positional.shift() ?? "serve";
    return { command, positional, flags };
}
function num(flags, key, fallback) {
    const raw = flags[key];
    if (typeof raw !== "string")
        return fallback;
    const parsed = Number(raw);
    return Number.isInteger(parsed) ? parsed : fallback;
}
async function main() {
    const { command, positional, flags } = parseArgs(process.argv.slice(2));
    if (flags.version || command === "version") {
        process.stdout.write(`${packageVersion()}\n`);
        return;
    }
    if (flags.help || command === "help") {
        printHelp();
        return;
    }
    const pluginPort = num(flags, "plugin-port", envPort("ASEPRITE_AI_PLUGIN_PORT", DEFAULT_PLUGIN_PORT));
    const controlPort = num(flags, "control-port", envPort("ASEPRITE_AI_CONTROL_PORT", pluginPort + 1));
    switch (command) {
        case "serve":
            return serve({
                pluginPort,
                controlPort,
                allowLua: truthy(flags.allowLua ?? process.env.ASEPRITE_AI_ALLOW_LUA),
                // Plugin manifests set ASEPRITE_AI_PROMPTS=0; see ServerOptions.prompts.
                prompts: process.env.ASEPRITE_AI_PROMPTS !== "0",
                headless: truthy(flags.headless ?? process.env.ASEPRITE_AI_HEADLESS),
                asepritePath: typeof flags.aseprite === "string" ? flags.aseprite : undefined,
                open: openList(typeof flags.open === "string" ? flags.open : process.env.ASEPRITE_AI_OPEN),
            });
        case "bridge":
            return runBridge({ pluginPort, controlPort });
        case "install":
            return runInstall(positional, flags);
        case "install-extension":
            return runInstallExtension(flags);
        case "doctor":
            return doctor({ pluginPort, controlPort });
        default:
            process.stderr.write(`Unknown command '${command}'.\n\n`);
            printHelp();
            process.exitCode = 2;
    }
}
async function serve(opts) {
    const { server, live } = createServer({
        pluginPort: opts.pluginPort,
        controlPort: opts.controlPort,
        allowLua: opts.allowLua,
        prompts: opts.prompts,
        headless: opts.headless,
        asepritePath: opts.asepritePath,
    });
    const transport = new StdioServerTransport();
    await server.connect(transport);
    // Headless only: open the operator's documents before the agent's first call,
    // so a batch run starts the way a live one does — with the file already open.
    // Never in live mode: there the user opens files, not the server.
    if (opts.open.length > 0) {
        if (live.mode !== "headless") {
            process.stderr.write("[aseprite-ai-artist] --open only applies with --headless; ignoring it\n");
        }
        else {
            for (const file of opts.open) {
                const full = path.resolve(file);
                try {
                    await live.call("sprite.manage", { op: "open", path: full });
                    process.stderr.write(`[aseprite-ai-artist] opened ${full}\n`);
                }
                catch (err) {
                    process.stderr.write(`[aseprite-ai-artist] could not open ${full}: ${err.message}\n`);
                }
            }
        }
    }
    const shutdown = () => {
        live.close();
        // .finally() forwards a rejection, and nothing would catch it. Exit on both
        // paths explicitly rather than relying on process.exit winning the race.
        server.close().then(() => process.exit(0), () => process.exit(1));
    };
    process.on("SIGINT", shutdown);
    process.on("SIGTERM", shutdown);
}
async function runBridge(opts) {
    const bridge = new Bridge({
        pluginPort: opts.pluginPort,
        controlPort: opts.controlPort,
        version: packageVersion(),
        log: (msg) => process.stderr.write(`[bridge] ${msg}\n`),
    });
    const started = await bridge.start();
    if (!started) {
        // Losing the race is the normal outcome when a bridge already runs.
        process.stderr.write("[bridge] another bridge already owns these ports; exiting\n");
        return;
    }
    const stop = () => bridge.stop().then(() => process.exit(0), () => process.exit(1));
    process.on("SIGINT", stop);
    process.on("SIGTERM", stop);
    // Hold the process open; the WebSocket servers keep the loop alive anyway.
    await new Promise(() => { });
}
async function runInstall(positional, flags) {
    const requested = positional.length > 0 ? positional : (flags.all ? CLIENTS : []);
    if (requested.length === 0) {
        process.stderr.write(`Name at least one client, or pass --all.\nAvailable: ${CLIENTS.join(", ")}\n`);
        process.exitCode = 2;
        return;
    }
    const scope = flags.project ? "project" : "user";
    const projectDir = typeof flags.dir === "string" ? flags.dir : process.cwd();
    const dryRun = truthy(flags["dry-run"]);
    const env = {};
    if (typeof flags.aseprite === "string")
        env.ASEPRITE_PATH = flags.aseprite;
    if (truthy(flags.allowLua))
        env.ASEPRITE_AI_ALLOW_LUA = "1";
    if (truthy(flags.headless))
        env.ASEPRITE_AI_HEADLESS = "1";
    const opts = {
        scope: scope,
        projectDir,
        command: "npx",
        args: ["-y", "@pebbly/aseprite-ai-artist@latest", "serve"],
        env,
        dryRun,
    };
    for (const name of requested) {
        if (!CLIENTS.includes(name)) {
            process.stderr.write(`Unknown client '${name}'. Available: ${CLIENTS.join(", ")}\n`);
            process.exitCode = 2;
            return;
        }
    }
    for (const name of requested) {
        try {
            const result = install(name, opts);
            if (dryRun) {
                process.stdout.write(`\n# ${name} → ${result.file}\n${result.note ?? ""}\n`);
            }
            else {
                process.stdout.write(`✓ ${name.padEnd(9)} ${result.file}\n`);
            }
        }
        catch (err) {
            process.stdout.write(`✗ ${name.padEnd(9)} ${err.message}\n`);
            process.exitCode = 1;
        }
    }
    if (truthy(flags.agents)) {
        const target = typeof flags.agents === "string" ? flags.agents : `${projectDir}/AGENTS.md`;
        const res = mergeAgentsFile(target, dryRun);
        process.stdout.write(`${res.written ? "✓" : "·"} AGENTS.md ${res.file}\n`);
    }
    if (!dryRun) {
        process.stdout.write("\nRestart the agent so it picks up the new server, then run `install-extension` if you have not already.\n");
    }
}
async function runInstallExtension(flags) {
    try {
        const result = installExtension({
            dryRun: truthy(flags["dry-run"]),
            configDir: typeof flags.dir === "string" ? flags.dir : undefined,
        });
        process.stdout.write(`✓ extension → ${result.target}\n`);
        process.stdout.write("Restart Aseprite. The extension connects on startup; check Edit ▸ Preferences ▸ Extensions if it does not appear.\n");
    }
    catch (err) {
        process.stdout.write(`✗ ${err.message}\n`);
        process.exitCode = 1;
    }
}
async function doctor(opts) {
    const lines = [`aseprite-ai-artist ${packageVersion()}`, ""];
    const configDir = findAsepriteConfigDir();
    lines.push(configDir
        ? `✓ Aseprite config dir   ${configDir}`
        : "✗ Aseprite config dir   not found — is Aseprite installed and has it been run once?");
    // Headless mode needs the executable, not the config dir, and finds it on
    // its own. Reported either way: "which Aseprite would --headless run" is the
    // first question when it fails.
    const binary = findAsepriteBinary();
    lines.push(binary
        ? `✓ Aseprite executable   ${binary} (used by --headless)`
        : "· Aseprite executable   not found — only needed for --headless; set ASEPRITE_PATH");
    // Probe before spawning anything. "The bridge is up" and "the bridge is up
    // because I just started it" are different answers, and only the first is a
    // diagnosis — reporting the second as a tick tells the user their setup works
    // when all that works is this command.
    const probe = new LiveClient({
        controlPort: opts.controlPort,
        pluginPort: opts.pluginPort,
        autoSpawnBridge: false,
        log: () => { },
    });
    const wasAlreadyRunning = await probe.waitForBridge(1_500);
    probe.close();
    // Reaching Aseprite at all requires a bridge — the extension connects to it,
    // not to us — so start one when there is none, and stop it again below.
    const live = new LiveClient({
        controlPort: opts.controlPort,
        pluginPort: opts.pluginPort,
        autoSpawnBridge: !wasAlreadyRunning,
        log: () => { },
    });
    const bridgeUp = await live.waitForBridge(4_000);
    const pluginUp = bridgeUp ? await live.waitForPlugin(4_000) : false;
    lines.push(...linkLines({
        bridgeUp,
        wasAlreadyRunning,
        pluginUp,
        controlPort: opts.controlPort,
        extensionVersion: live.hello?.extensionVersion,
        asepriteVersion: live.hello?.asepriteVersion,
        serverVersion: packageVersion(),
    }));
    if (pluginUp) {
        lines.push(`  features               ${live.features.join(", ") || "(none)"}`);
        try {
            const site = await live.call("session.site");
            lines.push(site.sprite
                ? `✓ Active sprite          ${site.sprite.name ?? "untitled"}`
                : "· Active sprite          none open (that is fine)");
        }
        catch (err) {
            lines.push(`✗ Round trip             ${err.message}`);
        }
    }
    lines.push("");
    lines.push("Client config locations:");
    for (const client of CLIENTS) {
        lines.push(`  ${client.padEnd(9)} ${configPath(client, {
            scope: "user",
            projectDir: process.cwd(),
            command: "",
            args: [],
            env: {},
            dryRun: true,
        })}`);
    }
    live.close();
    // A diagnostic must not leave a daemon behind. Only ever the one this run
    // started: a bridge that was already there belongs to a live session.
    const startedPid = live.spawnedBridgePid;
    if (startedPid !== null) {
        try {
            process.kill(startedPid);
            lines.push("", `· Stopped the bridge this check started (pid ${startedPid}).`);
        }
        catch {
            // Already gone — it lost the port race, or exited on its own.
        }
    }
    process.stdout.write(lines.join("\n") + "\n");
    process.exitCode = pluginUp ? 0 : 1;
}
function printHelp() {
    process.stdout.write(`aseprite-ai-artist ${packageVersion()} — agent control layer for Aseprite

Usage:
  aseprite-ai-artist [serve]                 Speak MCP over stdio (what agents run)
  aseprite-ai-artist bridge                  Run the WebSocket relay (usually auto-started)
  aseprite-ai-artist install <client…>       Write MCP config for an agent
  aseprite-ai-artist install-extension       Install the Aseprite Lua extension
  aseprite-ai-artist doctor                  Diagnose a broken setup

Clients: ${CLIENTS.join(", ")}

Options:
  --all                Install for every supported client
  --project            Write project-scoped config instead of user-scoped
  --dir <path>         Project directory (default: cwd)
  --agents [path]      Also write an AGENTS.md section (default: ./AGENTS.md)
  --aseprite <path>    Path to the Aseprite executable (headless mode; written as ASEPRITE_PATH by install)
  --allowLua           Enable the run_lua escape hatch (arbitrary code in Aseprite)
  --headless           Run a batch Aseprite this server owns instead of driving an open window
  --open <files>       Headless: open these documents at startup (separated by '${path.delimiter}'; env ASEPRITE_AI_OPEN)
  --plugin-port <n>    Port the Aseprite extension dials (default ${DEFAULT_PLUGIN_PORT})
  --control-port <n>   Port MCP servers dial (default ${DEFAULT_CONTROL_PORT})
  --dry-run            Print what would change, write nothing
  --version, --help

Examples:
  npx @pebbly/aseprite-ai-artist install --all --agents
  npx @pebbly/aseprite-ai-artist install codex cursor --project
  npx @pebbly/aseprite-ai-artist doctor
  npx @pebbly/aseprite-ai-artist serve --headless --aseprite /Applications/Aseprite.app/Contents/MacOS/aseprite
`);
